export function projectEntity0150<K extends keyof Entity0150>(entity: Entity0150, keys: readonly K[]): Pick<Entity0150, K> {
  const result = {} as Pick<Entity0150, K>
  for (const key of keys) {
    result[key] = entity[key]
  }
  return result
}

export function patchEntity0150(entity: Entity0150, patch: Entity0150Patch): Entity0150 {
  return { ...entity, ...patch }
}

export function summarizeEntity0150(entity: Entity0150): Entity0150Summary {
  return {
    label: entity.title.trim() || entity.id,
    total: metricKeys.reduce((sum, key) => sum + entity[key], 0),
    active: entity.active && entity.status !== 'archived',
  }
}

